const CEFR_ORDER = ["A1", "A2", "B1", "B2", "C1", "C2"];

function normalizeLevel(level) {
  const value = String(level || "B1").toUpperCase();
  if (value.includes("C2")) return "C2";
  if (value.includes("C1")) return "C1";
  if (value.includes("B2")) return "B2";
  if (value.includes("B1")) return "B1";
  if (value.includes("A2")) return "A2";
  return "A1";
}

function normalizeTopicText(value) {
  return String(value || "")
    .toLowerCase()
    .replace(/[“”]/g, '"')
    .replace(/[’]/g, "'")
    .replace(/[^a-z0-9+\/\s'-]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function topicKeywords(topic) {
  const base = normalizeTopicText(topic);
  const words = base.split(" ").filter((word) => word.length > 2);
  const phrases = [base];
  if (base.includes("articles")) phrases.push("article", "a an the", "a/an/the", "zero article");
  if (base.includes("tenses")) phrases.push("tenses", "tense", "all tenses", "mixed tenses");
  if (base.includes("conditionals")) phrases.push("conditional", "conditionals", "if clauses");
  if (base.includes("reported speech")) phrases.push("reported speech", "indirect speech");
  if (base.includes("phrasal verbs")) phrases.push("phrasal verb", "phrasal verbs");
  if (base.includes("word formation")) phrases.push("word formation");
  if (base.includes("prepositions")) phrases.push("preposition", "prepositions");
  if (base.includes("question words")) phrases.push("what where when who why how", "question words");
  if (base.includes("how much")) phrases.push("how much", "how many");
  if (base.includes("some")) phrases.push("some any", "some", "any");
  return Array.from(new Set([...phrases, words.join(" ")]));
}

function findCatalogTopic(text, preferredLevel = "B1") {
  const query = normalizeTopicText(text);
  if (!query) return null;

  const matches = [];
  for (const level of CEFR_ORDER) {
    const levelData = CEFR_LEVEL_TOPICS[level];
    for (const kind of ["grammar", "vocabulary"]) {
      for (let index = 0; index < levelData[kind].length; index += 1) {
        const row = levelData[kind][index];
        const keys = topicKeywords(row.topic);
        const direct = keys.some((key) => key && (query.includes(key) || key.includes(query)));
        const allMainWords = normalizeTopicText(row.topic).split(" ").filter((word) => word.length > 3);
        const wordMatch = allMainWords.length > 0 && allMainWords.every((word) => query.includes(word));
        if (direct || wordMatch) {
          matches.push({ ...row, level, kind, index, id: `catalog|${level}|${kind}|${index}` });
        }
      }
    }
  }

  if (!matches.length) return null;

  const preferredIndex = CEFR_ORDER.indexOf(normalizeLevel(preferredLevel));
  let best = matches[0];
  let bestScore = -999;
  for (const match of matches) {
    const levelIndex = CEFR_ORDER.indexOf(match.level);
    const notAbove = levelIndex <= preferredIndex ? 10 : 0;
    const closeness = -Math.abs(preferredIndex - levelIndex);
    const kindScore = match.kind === "grammar" ? 1 : 0;
    const score = notAbove + closeness + kindScore;
    if (score > bestScore) {
      bestScore = score;
      best = match;
    }
  }
  return best;
}

function getCatalogTopicById(topicId) {
  if (!String(topicId).startsWith("catalog|")) return null;
  const [, level, kind, indexText] = String(topicId).split("|");
  const row = CEFR_LEVEL_TOPICS[level]?.[kind]?.[Number(indexText)];
  if (!row) return null;
  return { ...row, level, kind, index: Number(indexText), id: topicId };
}

function getLevelTopicSummary(level) {
  const safeLevel = normalizeLevel(level);
  const data = CEFR_LEVEL_TOPICS[safeLevel] || CEFR_LEVEL_TOPICS.B1;
  const grammar = data.grammar.map((row) => row.topic).join(", ");
  const vocabulary = data.vocabulary.map((row) => row.topic).join(", ");
  return `${safeLevel} grammar topics: ${grammar}\n${safeLevel} vocabulary topics: ${vocabulary}`;
}

function catalogLevelAdvice(studentLevel, topicLevel) {
  const studentIndex = CEFR_ORDER.indexOf(normalizeLevel(studentLevel));
  const topicIndex = CEFR_ORDER.indexOf(normalizeLevel(topicLevel));
  if (topicIndex > studentIndex) return "This is a little above your current level, so I will explain it simply first.";
  if (topicIndex < studentIndex) return "This is a useful review topic for your level.";
  return "This topic fits your current level.";
}

function catalogExample(row, scene, version = 0) {
  const p = scene.people[version % scene.people.length];
  const noun = scene.nouns[version % scene.nouns.length];
  const v = scene.verbs[version % scene.verbs.length];
  const topic = normalizeTopicText(row.topic);

  if (topic.includes("to be")) return `${p} is interested in the ${noun}.`;
  if (topic.includes("pronouns")) return `${p} likes the ${noun}. He/She talks about it.`;
  if (topic.includes("possessive")) return `This is ${p}'s ${noun}. It is his/her ${noun}.`;
  if (topic.includes("article")) return `${p} saw a ${noun}. The ${noun} was interesting.`;
  if (topic.includes("plural")) return `One ${noun}, two ${noun}s.`;
  if (topic.includes("this") || topic.includes("that")) return `This ${noun} is here. That ${noun} is there.`;
  if (topic.includes("there is")) return `There is a ${noun}. There are many ${noun}s.`;
  if (topic.includes("have got")) return `${p} has got a ${noun}.`;
  if (topic.includes("present simple")) return `${p} ${v.s} the ${noun} every day.`;
  if (topic.includes("present continuous")) return `${p} is ${v.ing} the ${noun} now.`;
  if (topic.includes("past simple")) return `${p} ${v.past} the ${noun} yesterday.`;
  if (topic.includes("past continuous")) return `${p} was ${v.ing} the ${noun} at 8 p.m.`;
  if (topic.includes("present perfect")) return `${p} has ${v.v3} the ${noun}.`;
  if (topic.includes("past perfect")) return `${p} had ${v.v3} the ${noun} before the lesson started.`;
  if (topic.includes("future")) return `${p} will ${v.base} the ${noun} tomorrow.`;
  if (topic.includes("conditional")) return `If ${p} ${v.s} the ${noun}, ${p} will improve.`;
  if (topic.includes("reported speech")) return `${p} said that he/she ${v.past} the ${noun}.`;
  if (topic.includes("passive")) return `The ${noun} is ${v.v3} by ${p}.`;
  if (topic.includes("relative")) return `${p} is the person who ${v.s} the ${noun}.`;
  if (topic.includes("gerund") || topic.includes("infinitive")) return `${p} enjoys ${v.ing} the ${noun}, but wants to ${v.base} more.`;
  if (topic.includes("modal")) return `${p} might ${v.base} the ${noun}.`;
  if (topic.includes("inversion")) return `Rarely does ${p} ${v.base} the ${noun} without preparation.`;
  if (topic.includes("vocabulary") || row.kind === "vocabulary") return `${scene.label}: ${noun}, ${scene.nouns[(version + 1) % scene.nouns.length]}, ${scene.nouns[(version + 2) % scene.nouns.length]}.`;
  return `${p} ${v.s} the ${noun}.`;
}

function catalogExplanation(row, user, scene, version = 0) {
  const level = row.level;
  const studentLevel = normalizeLevel(user?.level || "B1");
  const advice = catalogLevelAdvice(studentLevel, level);
  const kind = row.kind === "vocabulary" ? "Vocabulary" : "Grammar";
  const example = catalogExample(row, scene, version);

  return `${row.topic} (${level} ${kind})\n\n${advice}\n\nWhat you learn: ${row.learns}.\n\nSimple explanation: This topic helps you understand and use ${row.topic} correctly in real English. At ${level}, focus on meaning first, then form, then your own examples.\n\nExample based on your interest:\n${example}\n\nYou can continue asking me questions, or start a quiz anytime using the quiz button.`;
}

function catalogQuiz(row, user, seedText = "", version = 0) {
  const scene = localScene(user, seedText);
  const p = scene.people[version % scene.people.length];
  const noun = scene.nouns[version % scene.nouns.length];
  const v = scene.verbs[version % scene.verbs.length];
  const example = catalogExample(row, scene, version);
  const topic = normalizeTopicText(row.topic);

  if (row.kind === "vocabulary") {
    return [
      makeQuestion(`Which word belongs to the topic "${row.topic}"?`, noun, ["because", "although", "quickly"], `${noun} is connected to ${row.topic}.`, version),
      makeQuestion(`Choose the best sentence about ${row.topic}.`, `${p} talks about the ${noun}.`, [`${p} talks the ${noun}.`, `${p} talking about the ${noun}.`, `${p} talk about the ${noun}.`], "Use a complete sentence with a subject and verb.", version + 1),
      makeQuestion(`What is this topic mainly about?`, row.topic, ["Advanced punctuation", "Verb endings only", "Mathematics"], `${row.topic} is a vocabulary topic.`, version + 2),
      makeQuestion(`Choose the useful phrase for ${row.topic}.`, `${noun} and ${scene.nouns[(version + 1) % scene.nouns.length]}`, ["do did done", "a/an/the", "if would had"], "Vocabulary topics group related words together.", version + 3),
      makeQuestion(`Why do we study ${row.topic}?`, "To understand and talk about this real-life area", ["Only to memorize grammar formulas", "Only to pass one question", "To avoid speaking"], "Vocabulary helps communication in real situations.", version + 4),
    ];
  }

  if (topic.includes("article")) return localQuiz("articles", user, seedText, version);
  if (topic.includes("reported speech")) return localQuiz("reported_speech", user, seedText, version);
  if (topic.includes("conditional")) return localQuiz("conditionals", user, seedText, version);
  if (topic.includes("present perfect")) return localQuiz("present_perfect", user, seedText, version);
  if (topic.includes("present continuous")) return localQuiz("present_continuous", user, seedText, version);
  if (topic.includes("past simple")) return localQuiz("past_simple", user, seedText, version);
  if (topic.includes("future") || topic.includes("tense")) return localQuiz("tenses_overview", user, seedText, version);

  return [
    makeQuestion(`What level is "${row.topic}" in this course map?`, row.level, ["A1", "A2", "B1", "B2", "C1", "C2"].filter((x) => x !== row.level).slice(0, 3), `${row.topic} is listed at ${row.level}.`, version),
    makeQuestion(`What does this topic teach?`, row.learns, ["only spelling", "only pronunciation", "only punctuation"], `It teaches: ${row.learns}.`, version + 1),
    makeQuestion(`Choose the best example for this topic.`, example, [`${p} ${v.base} ${noun}`, `${p} ${v.v3} ${noun}`, `${p} is ${v.base} ${noun}`], `Example: ${example}`, version + 2),
    makeQuestion(`Why is "${row.topic}" useful?`, "It helps you build clearer English sentences.", ["It is not useful.", "It only changes handwriting.", "It only teaches numbers."], `${row.topic} supports real communication.`, version + 3),
    makeQuestion(`What should you do after learning the rule?`, "Make your own example sentence.", ["Stop practicing.", "Avoid speaking.", "Forget the rule."], "Practice makes the rule usable.", version + 4),
  ];
}

